{"title": "Mapa de Rastreamento da Frota", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "config": {
    "kibana": {
      "type": "map",
      "latitude": -23.5613,
      "longitude": -46.656,
      "zoom": 11
    }
  },
  "data": [
    {
      "name": "veiculos",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "telemetria-frota-*",
        "body": {
          "size": 1000,
          "_source": [
            "latitude",
            "longitude",
            "velocidadeEmQuilometrosPorHora",
            "identificadorDoVeiculo"
          ]
        }
      },
      "format": {
        "property": "hits.hits"
      },
      "transform": [
        {
          "type": "geopoint",
          "projection": "projection",
          "fields": [
            "_source.longitude",
            "_source.latitude"
          ]
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "cor",
      "type": "threshold",
      "domain": [
        90
      ],
      "range": [
        "#54b399",
        "#bd271e"
      ]
    }
  ],
  "marks": [
    {
      "type": "symbol",
      "from": {
        "data": "veiculos"
      },
      "encode": {
        "enter": {
          "size": {
            "value": 90
          },
          "stroke": {
            "value": "#000000"
          },
          "strokeWidth": {
            "value": 0.5
          },
          "fillOpacity": {
            "value": 0.85
          }
        },
        "update": {
          "x": {
            "field": "x"
          },
          "y": {
            "field": "y"
          },
          "fill": {
            "scale": "cor",
            "field": "_source.velocidadeEmQuilometrosPorHora"
          },
          "tooltip": {
            "signal": "{'Veiculo': datum._source.identificadorDoVeiculo, 'Velocidade (km/h)': datum._source.velocidadeEmQuilometrosPorHora}"
          }
        }
      }
    }
  ]
}"}}

{"title": "Temperatura dos Motores ao Longo do Tempo", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": "Temperatura máxima dos motores",
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "@timestamp",
      "index": "telemetria-frota-*",
      "body": {
        "size": 0,
        "aggs": {
          "por_tempo": {
            "date_histogram": {
              "field": "@timestamp",
              "fixed_interval": "30s"
            },
            "aggs": {
              "temperatura_maxima": {
                "max": {
                  "field": "temperaturaDoMotorEmGrausCelsius"
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.por_tempo.buckets"
    }
  },
  "layer": [
    {
      "mark": {
        "type": "line",
        "point": true,
        "color": "#e7664c"
      },
      "encoding": {
        "x": {
          "field": "key",
          "type": "temporal",
          "title": "Tempo"
        },
        "y": {
          "field": "temperatura_maxima.value",
          "type": "quantitative",
          "title": "Temperatura (°C)"
        }
      }
    },
    {
      "mark": {
        "type": "rule",
        "color": "#bd271e",
        "strokeDash": [
          4,
          4
        ]
      },
      "encoding": {
        "y": {
          "datum": 100
        }
      }
    }
  ]
}"}}
